struct MaxFlowSolver{
	int head[MAXN], v[M], nxt[M], capacity[M], flow[M], totalEdges;
	int dist[MAXN], current[MAXN];
	int s, t;
	void initialize(){
		memset(head, -1, sizeof head); totalEdges=0;
	}
	void addEdge(int u, int v, int c){
		v[M]=v; nxt[M]=head[u]; capacity[M]=c; flow[M]=0; head[u]=totalEdges++;
		v[M]=u; nxt[M]=head[v]; capacity[M]=0; flow[M]=0; head[v]=totalEdges++;
	}
	bool buildLevelGraph(){
		memset(dist, -1, sizeof dist);
		dist[s]=0;
		queue<int> q;
		q.push(s);
		while(!q.empty()){
			int u=q.front(); q.pop();
			for(int i=head[u]; ~i; i=nxt[i]){
				int v=v[i];
				if(dist[v]==-1 && capacity[i]>flow[i]){
					dist[v]=dist[u]+1;
					q.push(v);
				}
			}
		}
		return dist[t]!=-1;
	}
	int sendFlow(int u, int flowIn){
		if(u==t || flowIn==0) return flowIn;
		int totalFlow=0, pushed;
		for(int &i=current[u]; ~i; i=nxt[i]){
			int v=v[i];
			if(dist[v]==dist[u]+1 && (pushed=sendFlow(v, min(flowIn, capacity[i]-flow[i])))>0){
				flow[i]+=pushed;
				flow[i^1]-=pushed;
				flowIn-=pushed;
				totalFlow+=pushed;
				if(flowIn==0) break;
			}
		}
		return totalFlow;
	}
	int maxFlow(int s, int t){
		s=s; t=t;
		int total=0;
		while(buildLevelGraph()){
			memcpy(current, head, sizeof head);
			total+=sendFlow(s, MAX_CAP);
		}
		return total;
	}
}maxFlowSolver;
